css:
/* Imported SVG design - generated by NoaCG Studio. Edit freely: this file is yours. */

/* ── Style contract: change these variables to retint the whole graphic. ── */
:root {
  --accent: #e8c547;           /* the one accent color */
  --text-color: #ffffff;          /* primary text */
  --text-dim: rgba(255,255,255,0.72);  /* secondary text (title line) */
  --panel-bg: rgba(12, 14, 18, 0.92);  /* the panel behind the text */
  --font-heading: "Inter", Arial, sans-serif;  /* the graphic's typeface */
  --scale: 1;                  /* whole-graphic size multiplier (also handles resolution) */
}

/* Bundled open-source font (the file ships with the export - no internet at playout).
   Declared as "Oswald-Medium" because that is the name this artwork's own CSS asks for; the file is Oswald. */
@font-face {
  font-family: "Oswald-Medium";
  src: url("fonts/oswald.woff2") format("woff2");
  font-weight: 500;            /* the name says this one weight, and the artwork states no other: pin the variable file to it */
  font-display: swap;          /* show fallback text until the font loads */
}
@font-face {
  font-family: "Oswald-Medium";
  src: url("fonts/oswald-latin-ext.woff2") format("woff2");
  font-weight: 500;            /* the name says this one weight, and the artwork states no other: pin the variable file to it */
  font-display: swap;
  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF;  /* latin-ext: Š Ž Ł ő ğ and the rest of Latin Extended */
}

/* Bundled open-source font (the file ships with the export - no internet at playout).
   Declared as "Oswald-Bold" because that is the name this artwork's own CSS asks for; the file is Oswald. */
@font-face {
  font-family: "Oswald-Bold";
  src: url("fonts/oswald.woff2") format("woff2");
  font-weight: 700;            /* the name says this one weight, and the artwork states no other: pin the variable file to it */
  font-display: swap;          /* show fallback text until the font loads */
}
@font-face {
  font-family: "Oswald-Bold";
  src: url("fonts/oswald-latin-ext.woff2") format("woff2");
  font-weight: 700;            /* the name says this one weight, and the artwork states no other: pin the variable file to it */
  font-display: swap;
  unicode-range: U+0100-02BA, U+02BD-02C5, U+02C7-02CC, U+02CE-02D7, U+02DD-02FF, U+0304, U+0308, U+0329, U+1D00-1DBF, U+1E00-1E9F, U+1EF2-1EFF, U+2020, U+20A0-20AB, U+20AD-20C4, U+2113, U+2C60-2C7F, U+A720-A7FF;  /* latin-ext: Š Ž Ł ő ğ and the rest of Latin Extended */
}

/* Reset and a transparent canvas (broadcast graphics render over video). */
* { margin: 0; padding: 0; box-sizing: border-box; }
html, body {
  width: 1920px;
  height: 1080px;
  overflow: hidden;                /* nothing ever scrolls on air */
  background: transparent;
  font-family: var(--font-heading);
}

/* ── Root position ── */
.imported-design {
  position: absolute;
  left: 0;                         /* the artwork is frame-sized - it covers the canvas as drawn */
  top: 0;
  opacity: 0;                      /* hidden until play() runs the entrance */
}

/* ── The design unit: the SVG and its bound text animate together as one box. ── */
.imported-design-box {
  position: relative;              /* a placed HTML field (over outlined text) positions against it */
  width: calc(1920px * var(--scale));  /* the artwork's own width drives the size */
  will-change: transform, opacity; /* hint the browser: this element animates */
}
.imported-design-art {
  display: block;
  width: 100%;                     /* fills the box - so --scale resizes art and text together */
  height: auto;                    /* the viewBox keeps the aspect */
}

/* Hidden data sources — holders SPX writes into and the runtime reads, never drawn.
   The rule lives in the stylesheet on purpose: an inline display:none would be wiped by the
   editor's entrance reset (it clears inline props) and the value would appear on screen. */
.noacg-data-source {
  display: none;                   /* input only: written by SPX, read by JS, never rendered */
}

