  "version": 2,
  "root": ".imported-design",
  "speed": 1,
  "steps": [
    {
      "name": "On air",
      "duration": 0.6,
      "ease": "sine.out",
      "calls": [
        { "time": 0, "call": "noacgRepaint" }
      ],
      "layers": {
        ".imported-design-box": {
          "opacity": [
            { "time": 0, "value": 0 },
            { "time": 0.6, "value": 1 }
          ]
        }
      }
    },
    {
      "name": "Out",
      "duration": 0.4,
      "ease": "sine.in",
      "layers": {
        ".imported-design-box": {
          "opacity": [
            { "time": 0, "value": 1 },
            { "time": 0.4, "value": 0 }
