    var q = svgPaintBox(shapes[j]);
    if (!(q.width > 0) || !(q.height > 0)) continue;
    var cover = Math.min(box.bottom, q.bottom) - Math.max(box.top, q.top);
    if (cover < box.height / 2) continue;
    var tol = Math.max(1, box.height / 2);
