      } else if (anchorWord === 'end') {
        extReach = box.right - (lb.penned ? halfGap : openPad(rightIn, rightDrawn, leftDrawn)) - lb.edge;
        room.penned = lb.penned;
      } else {
        extReach = rb.edge - (rb.penned ? halfGap : openPad(leftIn, leftDrawn, rightDrawn)) - box.left;
        room.penned = rb.penned;
      }
      room.width = Math.max(svgFitWidths[el.id], extReach * scale);
      var drawnRoom = under ? ext : drawnExt;
      room.height = Math.max(box.height * scale, (svgFitCeiling(el, drawnRoom, svgPanelTopPad(drawnRoom, nodes)) - box.top) * scale);
      room.top = el.getBBox ? el.getBBox().y : 0;
    }
    // NEVER PAST THE FRAME, whatever the box says (review of 2026-11-20): a bar that bleeds off the
    // artboard, or a clip, cuts off text the room would otherwise grant. Only ever narrows.
    if (box.width > 0) {
      var fr = svgFrameOf(el);
      var aw = room.anchorWord || (align && align.h) || 'start';
      // Where the line grows FROM: the anchor the snap puts it on, where there is one, else its
      // drawn edge or middle.
      var ax = aw === 'middle' ? (box.left + box.right) / 2 : (aw === 'end' ? box.right : box.left);
      if (!room.anchorWord && align && align.anchor != null && el.getBBox) ax = box.left + (align.anchor - el.getBBox().x) / scale;
      var most = aw === 'middle' ? 2 * Math.min(ax - fr.left, fr.right - ax) : (aw === 'end' ? ax - fr.left : fr.right - ax);
      if (most * scale < room.width) room.width = Math.max(svgFitWidths[el.id], most * scale);
    }
    svgFitRoom[el.id] = room;
  }
  // TWO LINES THAT GROW TOWARDS EACH OTHER SHARE THE GAP between them. A ticker's story fills
  // rightwards and its end-anchored source leftwards: bounded each by where the other was DRAWN,
  // both may fill the same gap, and with two long values they painted over each other,
  // unreported (#1148). The room is measured once, at rest, so it cannot depend on which value is
  // the long one: they meet at the middle of the gap, unless the right one could never reach that
  // far left anyway (a score figure penned on its other side), and then where it stops is the
  // left one's bound. Each keeps its half type short of where they meet.
  for (var f = 0; f < facing.length; f++) {
    var pair = facing[f];
    var left = null;
    for (var n = 0; n < nodes.length; n++) if (nodes[n].contains(pair.near)) { left = nodes[n]; break; }
    var leftRoom = left && svgFitRoom[left.id];
    var l = left && measured[left.id];
    var r = measured[pair.right.id];
    var penned = left && penNear[left.id];
    if (!l || !leftRoom.align || leftRoom.align.h === 'end' || !penned || !pair.right.contains(penned)) continue;
    var middle = (l.box.right + r.box.left + pair.shift) / 2;
    var meet = Math.max(middle, pair.reach);
    leftRoom.width = Math.max(svgFitWidths[left.id], Math.min(leftRoom.width, (meet - l.gap - l.box.left) * l.scale));
    if (pair.reach < middle) {
      var rightRoom = svgFitRoom[pair.right.id];
      rightRoom.width = Math.max(svgFitWidths[pair.right.id], Math.min(rightRoom.width, (r.box.right + pair.shift - r.gap - middle) * r.scale));
    }
  }
  // Put each value back in the shape it was in - the drawn LINES where the value is the drawn
  // one, so a block skipped by the ladder is not left flattened (measureSvgBudgets says why).
  for (var b = 0; b < nodes.length; b++) {
    if (!swapped[b]) continue;
    if (live[b] === svgFitDrawn[nodes[b].id]) svgShowDrawn(nodes[b], live[b]);
    else nodes[b].textContent = live[b];
  }
}

/** THE LINES AN OPERATOR BROKE ON PURPOSE (#1977, owner: "preserve intentional line breaks
 *  while retaining the existing wrapping, fitting and shrinking rules"). A Sheet cell or a typed
 *  value holding "Doors open at 19:00" over "Tickets at the door" means two lines, and reading it
 *  as words reflowed them into one paragraph on air with nothing reporting it.
 *
 *  Each break is a HARD line boundary; the ladder then wraps, fits and shrinks within and across
 *  those lines exactly as before. A value with no break answers [value], untouched, so it takes
 *  the very same path it always did. So does the DRAWN value: a hand-written file may carry a
 *  newline inside its own text that SVG shows as a space, and the artwork at rest stays the
 *  artwork. Blank lines fold into the break around them, since an empty tspan carries no glyph
 *  for its dy to move and would be lost anyway. */
function svgHardLines(el, value) {
  var text = String(value);
