      if (moves[j].el !== moves[i].el && moves[j].el.contains(moves[i].el)) { inside = true; break; }
    }
    if (inside) continue;
    var item = noacgPlaceOf(moves[i].el);
    if (typeof gsap !== 'undefined') gsap.killTweensOf(item);
    if (reason === 'data' && typeof gsap !== 'undefined' && (item.dx !== moves[i].dx || item.dy !== moves[i].dy)) {
      gsap.to(item, {
        dx: moves[i].dx,
        dy: moves[i].dy,
        duration: 0.6 / motionSpeed(),
        ease: 'power2.inOut',
        onUpdate: noacgPlaceWrite,
        onUpdateParams: [item]
      });
    } else {
      item.dx = moves[i].dx;
      item.dy = moves[i].dy;
      noacgPlaceWrite(item);
    }
  }
}

// noacgRepaintWith(reason): the whole graphic, from the table. ONE function for every driver,
// so a state entry, a data write, a tick and a snap recovery cannot describe the same board
// four different ways - they differ only in what travels.
function noacgRepaintWith(reason) {
  if (typeof NOACG_BEHAVIOUR === 'undefined') return;
  noacgRememberNumbers();
  var kinds = NOACG_BEHAVIOUR.kinds || {};
  for (var kid in kinds) {
    if (Object.prototype.hasOwnProperty.call(kinds, kid) && noacgKinds[kinds[kid].kind] && noacgKinds[kinds[kid].kind].report) {
      noacgKinds[kinds[kid].kind].report(kid, kinds[kid]);
    }
  }
  var rules = NOACG_BEHAVIOUR.paint || [];
  // Looks first: any rule naming a token turns it on; a token no rule holds for goes off.
  var lit = {}, pops = {}, seen = {}, defaults = {}, moves = {};
  var plates = {};                // row key ('' for none) -> its lit looks, for the readout inks
  var r, rule, keys, k;
  for (r = 0; r < rules.length; r++) {
    rule = rules[r];
    if (!rule.look) continue;
    keys = rule.row ? [rule.row] : rule.rows ? noacgRowsOf(rule.rows) : [null];
    for (k = 0; k < keys.length; k++) {
      var token = noacgRoleToken(rule.look, keys[k]);
      seen[token] = true;
      if (rule['default'] && !defaults[token]) defaults[token] = { rule: rule, key: keys[k] };
      if (noacgHolds(rule.when, keys[k])) {
        lit[token] = true;
        if (rule.enter === 'pop' && reason === 'state') pops[token] = true;
        // A pulse or a flash follows the rule on EVERY repaint: the clock's tick is what lights
        // a countdown's last stretch and its zero.
        if (rule.enter === 'pulse' || rule.enter === 'flash') moves[token] = rule.enter;
      }
    }
  }
  for (var t in seen) {
    if (!Object.prototype.hasOwnProperty.call(seen, t)) continue;
    var slash = t.indexOf('/');
    var els = noacgRoleEls(slash === -1 ? t : t.slice(0, slash), slash === -1 ? null : t.slice(slash + 1));
    // Drew nothing for this moment: NoaCG's own look stands in, built once (the ladder's rung 1).
    if (els.length === 0 && defaults[t]) {
      var made = noacgDefaultEl(defaults[t].rule, defaults[t].key);
      els = made ? [made] : els;
    }
    var plateRow = slash === -1 ? '' : t.slice(slash + 1);
    for (var e = 0; e < els.length; e++) {
      var appeared = noacgLookShow(els[e], !!lit[t]);
      if (lit[t] && pops[t]) noacgPop(els[e]);
      noacgMove(els[e], lit[t] ? moves[t] : undefined, appeared);
      if (lit[t]) (plates[plateRow] = plates[plateRow] || []).push(els[e]);
    }
  }
  // Gauges and readouts: from the data, every time.
  for (r = 0; r < rules.length; r++) {
    rule = rules[r];
    if (!rule.gauge && !rule.write) continue;
    keys = rule.row ? [rule.row] : rule.rows ? noacgRowsOf(rule.rows) : [null];
    for (k = 0; k < keys.length; k++) {
      var targets = noacgRoleEls(rule.gauge || rule.write, keys[k]);
      if (targets.length === 0) continue;
      var value = noacgDerive(rule.from, keys[k]);
      for (var g = 0; g < targets.length; g++) {
        if (rule.gauge) noacgGauge(targets[g], noacgRoleToken(rule.gauge, keys[k]), typeof value === 'number' ? value : 0, noacgGaugeMotion(rule.from, reason, k));
        else {
          // A readout with nothing to say is left as drawn - an empty round must not blank a
          // board the designer filled in.
          if (value !== null && value !== undefined && value !== '') noacgReadoutWrite(targets[g], String(value));
          noacgReadoutInk(targets[g], plates[keys[k] === null ? '' : String(keys[k])] || []);
        }
      }
    }
  }
  // Places last: the readouts above are already written, and a row moves as a whole.
  noacgPlaceAll(rules, reason);
}

// ── A readout keeps the alignment it was drawn with (#2691) ──────────────────────────
// Illustrator writes no text-anchor: a figure set right against its track arrives as point text
// at its measured left edge, so a written value longer than the sample grew rightwards past the
// track. A readout is not a fitted field, so svgAlignOf never sees it; the same reading is made
// here, once, off the DRAWN sample in the box the fit would choose (svgFitPanel, svgLocalBox,
// SVG_ALIGN_TOL), and a line drawn centred or against the right is anchored where it was drawn.
// Nothing moves: the anchor is the drawn centre or the drawn right edge, never the box's own.
// A line the file anchors already, or one drawn against the left, is written exactly as before.

// noacgDrawnAnchor(el): { h, x } for a readout drawn centred or right in its box, null for one
// that fills rightwards or whose file states its anchor, undefined while it cannot be measured
// (a look not yet showing). Asked with the drawn sample and the drawn attributes in place.
function noacgDrawnAnchor(el) {
  if (typeof svgFitPanel !== 'function' || typeof svgLocalBox !== 'function') return null;
  // A STATED anchor, start included, is the file's answer, as svgAlignOf believes it.
  if (/^(start|middle|end)$/.test(el.getAttribute('text-anchor') || '')) return null;
  var computed = getComputedStyle(el).textAnchor;
  if (computed === 'middle' || computed === 'end') return null;
  var own;
  try { own = el.getBBox(); } catch (e) { return undefined; }
  if (!(own.width > 0) || !(own.height > 0)) return undefined;
  var panel = svgFitPanel(el);
  var box = panel ? svgLocalBox(panel, el) : null;
  if (!box) return null;
  var tol = typeof SVG_ALIGN_TOL === 'number' ? SVG_ALIGN_TOL : 0.05;
  var cx = own.x + own.width / 2;
  if (Math.abs(cx - box.cx) <= (box.right - box.left) * tol) return { h: 'middle', x: cx };
  return cx > box.cx ? { h: 'end', x: own.x + own.width } : null;
}

// noacgReadoutWrite(el, text): write a readout's value, anchored as it was drawn. The drawn
// sample and attributes are kept, so a readout first written while hidden, or while its face was
// still loading, is measured again off the drawing rather than off whatever it says now.
function noacgReadoutWrite(el, text) {
  if (!/^text$/i.test(el.tagName || '')) { el.textContent = text; return; }
  var i;
  if (el.noacgDrawn === undefined) {
    el.noacgDrawn = { nodes: [], anchor: el.getAttribute('text-anchor'), x: el.getAttribute('x') };
    for (i = 0; i < el.childNodes.length; i++) el.noacgDrawn.nodes.push(el.childNodes[i].cloneNode(true));
  }
  if (el.noacgAnchor === undefined) {
    var d = el.noacgDrawn;
    while (el.firstChild) el.removeChild(el.firstChild);
    for (i = 0; i < d.nodes.length; i++) el.appendChild(d.nodes[i].cloneNode(true));
    if (d.anchor === null) el.removeAttribute('text-anchor'); else el.setAttribute('text-anchor', d.anchor);
    if (d.x === null) el.removeAttribute('x'); else el.setAttribute('x', d.x);
    var a0 = noacgDrawnAnchor(el);
    // MEASURED IN A FACE THAT HAS NOT LANDED is used for this write and not kept: the fallback
    // face has other widths, so the anchor is taken again off the drawing once fonts settle.
    if (a0 !== undefined && document.fonts && document.fonts.status === 'loading') noacgReadoutLater(el);
    else el.noacgAnchor = a0;
    el.noacgAnchorNow = a0;
  }
  var a = el.noacgAnchor !== undefined ? el.noacgAnchor : el.noacgAnchorNow;
  if (a) {
    if (el.getAttribute('text-anchor') !== a.h) el.setAttribute('text-anchor', a.h);
    var x = a.x.toFixed(2);
    if (el.getAttribute('x') !== x) el.setAttribute('x', x);
  }
  el.textContent = text;
}

// noacgReadoutLater(el): once the fonts settle, write the readout's current value again, so it is
// anchored off the drawing in the face it will be seen in.
var noacgReadoutsWaiting = null;
function noacgReadoutLater(el) {
  if (!noacgReadoutsWaiting) {
    noacgReadoutsWaiting = [];
    document.fonts.ready.then(function () {
      var waiting = noacgReadoutsWaiting;
      noacgReadoutsWaiting = null;
      for (var i = 0; i < waiting.length; i++) {
        if (waiting[i].noacgAnchor === undefined) noacgReadoutWrite(waiting[i], waiting[i].textContent);
      }
    });
  }
  if (noacgReadoutsWaiting.indexOf(el) === -1) noacgReadoutsWaiting.push(el);
}

// ── A readout stays legible on a look lit under it ──────────────────────────────────
// A bingo tile lights an amber plate under a numeral drawn white for the dark board, and white on
// amber is the one pairing there a room cannot read (#784). So a readout the board writes takes a
// dark or a light ink wherever a lit look of its own row sits under it and its drawn ink falls
// below 3:1 against that plate, and gets its drawn ink back the moment the plate goes. Only a
// solid fill is read; a gradient or a picture is left as the designer drew it.

// noacgLuminance(color): the relative luminance of "#rrggbb" or a computed "rgb(...)", or null
// for anything that is not a mostly opaque solid colour.
function noacgLuminance(color) {
  var hex = /^#([0-9a-f]{2})([0-9a-f]{2})([0-9a-f]{2})$/i.exec(color || '');
  var m = /rgba?\(([^)]+)\)/.exec(color || '');
  var p = hex ? [parseInt(hex[1], 16), parseInt(hex[2], 16), parseInt(hex[3], 16)] : m ? m[1].split(',') : null;
  if (!p || (p.length > 3 && parseFloat(p[3]) < 0.5)) return null;
  var lin = function (v) {
    v = parseFloat(v) / 255;
    return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4);
  };
  return 0.2126 * lin(p[0]) + 0.7152 * lin(p[1]) + 0.0722 * lin(p[2]);
}

function noacgContrast(a, b) {
  return (Math.max(a, b) + 0.05) / (Math.min(a, b) + 0.05);
}

// The two inks a readout may take: the dark NoaCG's own looks are drawn on, and its default ink.
var NOACG_INK_DARK = '#0d1017';
var NOACG_INK_DARK_L = noacgLuminance(NOACG_INK_DARK);
var NOACG_INK_LIGHT_L = noacgLuminance(NOACG_DEFAULT_INK);

// noacgPlateUnder(look, x, y): the luminance of the solid fill a look paints at a screen point -
// the topmost of its shapes there, itself included. A group's own fill is only what its children
// inherit, never paint, so a group is not read; a shadow drawn under the plate is not the plate.
var NOACG_SHAPES = 'rect, path, polygon, circle, ellipse';
function noacgPlateUnder(look, x, y) {
  var shapes = [].slice.call(look.querySelectorAll(NOACG_SHAPES));
  if (look.matches && look.matches(NOACG_SHAPES)) shapes.unshift(look);
  for (var i = shapes.length - 1; i >= 0; i--) {
    var b = shapes[i].getBoundingClientRect();
    if (x < b.left || x > b.right || y < b.top || y > b.bottom) continue;
    var s = getComputedStyle(shapes[i]);
    if (s.display === 'none' || parseFloat(s.fillOpacity) < 0.5) continue;
    var l = noacgLuminance(s.fill);
    if (l !== null) return l;
  }
  return null;
}

// noacgReadoutInk(el, plates): the ink a readout should wear over the lit looks of its row, set
// only when it differs from what it wears now. The drawn ink is read once, the first time a look
// is lit in its row, so a readout with nothing ever lit under it costs nothing.
function noacgReadoutInk(el, plates) {
  if (el.noacgDrawnFill === undefined) {
    if (!plates.length) return;
    el.noacgDrawnFill = el.style.getPropertyValue('fill');
    el.noacgDrawnInk = noacgLuminance(getComputedStyle(el).fill);
  }
  var want = el.noacgDrawnFill;
  if (plates.length && el.noacgDrawnInk !== null) {
    var box = el.getBoundingClientRect();
    var cx = box.left + box.width / 2;
    var cy = box.top + box.height / 2;
    for (var i = 0; i < plates.length; i++) {
      if (plates[i].contains(el)) continue;      // a look that IS the readout's own drawing
      var under = noacgPlateUnder(plates[i], cx, cy);
      if (under === null || noacgContrast(el.noacgDrawnInk, under) >= 3) continue;
      want = noacgContrast(under, NOACG_INK_DARK_L) >= noacgContrast(under, NOACG_INK_LIGHT_L) ? NOACG_INK_DARK : NOACG_DEFAULT_INK;
      break;
    }
  }
  if (el.noacgInk !== want) {
    el.noacgInk = want;
    el.style.fill = want;
  }
}

// noacgRepaint(): a STATE was entered - named by every recipe state's timeline. Snap replays
// states with callbacks suppressed and then runs the target's own calls, so this is also what
// puts the drawings back after a recovery.
function noacgRepaint() { noacgRepaintWith('state'); }
// noacgRepaintData(): update() wrote fields. A vote landing moves the bars without any
// transition firing; a live edit never erases a look the machine still holds.
function noacgRepaintData() { noacgRepaintWith('data'); }
// noacgRepaintTick(): the clock's own beat, with neither a state nor a write.
function noacgRepaintTick() { noacgRepaintWith('tick'); }

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', refitSvgText);
} else {
  refitSvgText();                               // DOM already parsed (e.g. an inline preview build)
}
if (document.fonts && document.fonts.ready) {
  document.fonts.ready.then(refitSvgText);
  // And whenever a face lands: in a page still parsing, ready can resolve before any layout has
  // asked for the face, and the one pass it buys is then taken in the fallback.
  if (document.fonts.addEventListener) document.fonts.addEventListener('loadingdone', refitSvgText);
}
// A DESIGN THAT WAS NOT ON SCREEN WHEN IT LOADED FITS WHEN IT ARRIVES. Both passes above run
// once, at load, and a document that is preloaded hidden (a playout renderer, a control page
// whose monitors are behind another workspace) has nothing for them to measure. It stays owed
// rather than wrong (svgFitLaidOut), and this is what pays the debt when no update() ever comes
// to. Guarded on the debt itself, so a hide-and-show cycle on a design that already has its
// answers costs nothing, and the panel growth this fit performs can never re-enter it.
if (typeof ResizeObserver === 'function') {
  var svgFitArt = document.querySelector('.imported-design-art');
  if (svgFitArt) {
    new ResizeObserver(function () {
      if (svgFitDue()) refitSvgText();
    }).observe(svgFitArt);
  }
}
